installer-gui-script.script:
function macOSVersionIsSupported() {
    var appleSilicon = system.sysctl('hw.optional.arm64') == 1;
    var minimum = appleSilicon ? '14.0' : '15.0';
    if (system.compareVersions(system.version.ProductVersion, minimum) >= 0) {
        return true;
    }
    my.result.type = 'Fatal';
    my.result.title = 'OMEGA needs macOS ' + minimum + ' or later';
    my.result.message = 'On ' + (appleSilicon ? 'an Apple Silicon' : 'an Intel') +
        ' Mac, OMEGA needs macOS ' + minimum + ' or later. Update macOS in ' +
        'System Settings, then run this installer again.';
    return false;
}
